<script setup lang="ts">
import { modelText, type DocumentRecord, type Station, type Page, type CommandResult } from '~/utils/types'
type WorkItem = DocumentRecord & { action?: 'CONFIRM_RECEIPT'|'READY'|'CONFIRM_RETURN'|null; action_route_step_id?: string }
const api=useApi();const {actor,courier,unitIds}=useSession();const station=ref('');const stations=ref<Station[]>([]);const docs=ref<WorkItem[]>([]);const cursor=ref<string|null>();const loading=ref(false);const saving=ref('');const error=ref<unknown>();const message=ref('');const mode=ref<'unit'|'courier'>(unitIds.value.length?'unit':'courier');const operation=ref<CommandResult>();let generation=0
const selection=ref<string[]>([]);const batchResult=ref<CommandResult>()
const selectedDocs=computed(()=>filteredDocs.value.filter(d=>selection.value.includes(d.id)))
const selectable=(d:WorkItem)=>d.process_sync_status==='APPLIED'&&(mode.value==='courier'||d.action==='CONFIRM_RECEIPT')
function selectAll(){selection.value=filteredDocs.value.filter(selectable).slice(0,100).map(d=>d.id)}
async function bulk(){const items=selectedDocs.value;if(!items.length)return;saving.value='bulk';error.value=undefined;try{const result=await api.command<CommandResult>(mode.value==='courier'?'/courier/reservations':`/stations/${station.value}/confirm-receipt`,{station_id:station.value,items:items.map(d=>({document_id:d.id,route_step_id:mode.value==='courier'?d.current_route_step_id:d.action_route_step_id,expected_version:d.version}))});batchResult.value=result;operation.value=result.process_sync_status==='APPLIED'?undefined:result;selection.value=[];await load()}catch(e){error.value=e}finally{saving.value=''}}
const modelFilter=ref('');const stateFilter=ref('');const states=computed(()=>[...new Set(docs.value.map(d=>d.business_state))]);const filteredDocs=computed(()=>docs.value.filter(d=>(!modelFilter.value||d.tracking_mode===modelFilter.value)&&(!stateFilter.value||d.business_state===stateFilter.value)))
const availableStations=computed(()=>stations.value.filter(s=>actor.value?.station_ids.includes(s.id)&&(mode.value==='courier'||unitIds.value.includes(s.unit_id))))
async function load(more=false){if(!station.value)return;const run=++generation;loading.value=true;error.value=undefined;try{const page=await api.get<Page<WorkItem>>(`/stations/${encodeURIComponent(station.value)}/${mode.value==='unit'?'unit-worklist':'worklist'}?limit=50${more&&cursor.value?`&cursor=${encodeURIComponent(cursor.value)}`:''}`);if(run!==generation)return;docs.value=more?[...docs.value,...page.items]:page.items;if(!more)selection.value=[];cursor.value=page.next_cursor}catch(e){if(run===generation)error.value=e}finally{if(run===generation)loading.value=false}}
async function changeMode(value:'unit'|'courier'){mode.value=value;modelFilter.value='';stateFilter.value='';docs.value=[];cursor.value=null;station.value=availableStations.value[0]?.id||'';await load()}
async function reserve(doc:DocumentRecord){saving.value=doc.id;error.value=undefined;message.value='';try{batchResult.value=await api.command<CommandResult>('/courier/reservations',{station_id:station.value,items:[{document_id:doc.id,route_step_id:doc.current_route_step_id,expected_version:doc.version}]});message.value='จองแล้ว ไปการจองของฉันเพื่อตรวจหนังสือจริงและถ่ายรูปก่อน Check รับ';await load()}catch(e){error.value=e}finally{saving.value=''}}
async function act(doc:WorkItem){if(!doc.action||!doc.action_route_step_id)return;saving.value=doc.id;error.value=undefined;message.value='';try{const step={route_step_id:doc.action_route_step_id,expected_version:doc.version};operation.value=doc.action==='CONFIRM_RECEIPT'?await api.command<CommandResult>(`/stations/${station.value}/confirm-receipt`,{station_id:station.value,items:[{document_id:doc.id,...step}]}):await api.command<CommandResult>(`/documents/${doc.id}/${doc.action==='READY'?'ready':'confirm-return'}`,step);message.value='บันทึกคำสั่งแล้ว รอ workflow ประสานก่อนทำขั้นตอนถัดไป';await load()}catch(e){error.value=e}finally{saving.value=''}}
const actionLabel=(action:WorkItem['action'])=>action==='READY'?'พร้อมจัดส่ง':action==='CONFIRM_RETURN'?'ยืนยันรับคืนต้นทาง':'ยืนยันรับหนังสือ'
onMounted(async()=>{try{stations.value=(await api.get<Page<Station>>('/stations')).items;station.value=availableStations.value[0]?.id||'';await load()}catch(e){error.value=e}})
onBeforeUnmount(()=>generation++)
</script>
<template><div class="page-head"><div><h1>งานประจำ Station</h1><p>Model B รอหน่วยงานพร้อมจัดส่ง ส่วน Model A ต้องพบหนังสือจริงก่อนรับ คิวรับ Courier แยกจากงานยืนยันรับของหน่วยงาน</p></div><NuxtLink v-if="courier" class="button" to="/reservations">การจองของฉัน</NuxtLink></div><Feedback :error="error" :message="message" /><BatchResult :result="batchResult" @refresh="selection=[];load()" /><div class="view-tabs" role="group" aria-label="เลือกประเภทงาน"><button v-if="unitIds.length" type="button" data-testid="station-unit-tab" class="button" :aria-pressed="mode==='unit'" @click="changeMode('unit')">งานหน่วยงาน</button><button v-if="courier" type="button" data-testid="station-courier-tab" class="button" :aria-pressed="mode==='courier'" @click="changeMode('courier')">คิวรับของ Courier</button><NuxtLink v-if="courier" class="button" to="/observations">บันทึกพบหนังสือข้าม Station</NuxtLink></div><OperationStatus v-if="operation" :operation-id="operation.operation_id" :sync-status="operation.process_sync_status" @applied="operation=undefined;load()" /><section class="panel"><form class="actions" @submit.prevent="load()"><div class="field"><label for="work-station">Station ที่มีสิทธิ์</label><select id="work-station" v-model="station" data-testid="station-select" required @change="docs=[];cursor=null;load()"><option disabled value="">เลือก Station</option><option v-for="s in availableStations" :key="s.id" :value="s.id">{{s.name}}</option></select></div><button class="button" :disabled="loading||!station">โหลดล่าสุด</button></form><UProgress v-if="loading" /><div v-if="!docs.length&&!loading" class="empty"><h2>{{availableStations.length?'ไม่มีรายการที่พร้อมดำเนินการ':'ไม่มีสิทธิ์ Station สำหรับงานนี้'}}</h2><p>{{mode==='courier'?'Model B รับได้เมื่อหน่วยงานพร้อม ส่วน Model A ต้องตรวจพบหนังสือจริงพร้อมรูป คิวแสดงเฉพาะงานที่ workflow ประสานแล้ว':'เลือก Station ที่สังกัดหน่วยงานและได้รับสิทธิ์ เพื่อยืนยันรับหรือพร้อมจัดส่ง'}}</p></div><DocumentFilters v-model:mode="modelFilter" v-model:state="stateFilter" :states="states" /><p v-if="docs.length&&!filteredDocs.length" class="empty">ไม่มีรายการตรงกับตัวกรอง ล้างตัวกรองหรือโหลดรายการเพิ่มเติม</p><div v-if="filteredDocs.some(selectable)" class="actions"><button type="button" class="button" :disabled="!!saving||!!operation" @click="selectAll">เลือกทั้งหมดที่ดำเนินการได้</button><button type="button" data-testid="bulk-submit" class="button primary" :disabled="!!saving||!!operation||!selectedDocs.length" @click="bulk">{{mode==='courier'?'จอง':'ยืนยันรับ'}} {{selectedDocs.length}} เรื่องที่เลือก</button><button v-if="selection.length" type="button" class="button" @click="selection=[]">ล้างที่เลือก</button><p class="hint">เลือกได้ครั้งละไม่เกิน 100 เรื่อง เรื่องที่พร้อมสำเร็จทันที เรื่องที่ชนกันจะแสดงเหตุผลแยกรายเรื่อง</p></div><div class="table-wrap"><table v-if="filteredDocs.length"><thead><tr><th>เลือก</th><th>หนังสือ</th><th>สถานะงาน</th><th>Workflow</th><th>ดำเนินการ</th></tr></thead><tbody><tr v-for="doc in filteredDocs" :key="doc.id"><td><label v-if="selectable(doc)" class="confirmation"><input v-model="selection" type="checkbox" :value="doc.id" :aria-label="`เลือกหนังสือ ${doc.title||doc.document_number||doc.id}`" :disabled="!!saving||!!operation||selection.length>=100&&!selection.includes(doc.id)" /></label></td><td><NuxtLink v-if="unitIds.includes(doc.origin_unit_id)" :to="`/documents/${doc.id}`">{{doc.title||doc.document_number||`หนังสือ #${doc.id.slice(-8)}`}}</NuxtLink><span v-else class="row-title">หนังสือ #{{doc.id.slice(-8)}}</span><p class="hint">{{modelText(doc.tracking_mode)}}</p></td><td><StatusTag :value="doc.business_state" /></td><td><StatusTag :value="doc.process_sync_status" /></td><td><button v-if="mode==='courier'" :data-testid="`reserve-${doc.id}`" class="button" :disabled="!!saving||!!operation||doc.process_sync_status!=='APPLIED'" @click="reserve(doc)">{{saving===doc.id?'กำลังจอง…':doc.tracking_mode==='MODEL_A'?'จองเพื่อตรวจหนังสือจริง':'จองหนังสือนี้'}}</button><button v-else-if="doc.tracking_mode==='MODEL_B'&&doc.action" :data-testid="`${doc.action==='READY'?'ready':doc.action==='CONFIRM_RETURN'?'return':'receipt'}-${doc.id}`" class="button primary" :disabled="!!saving||!!operation||doc.process_sync_status!=='APPLIED'" @click="act(doc)">{{saving===doc.id?'กำลังบันทึก…':actionLabel(doc.action)}}</button><p v-else class="hint">{{doc.process_sync_status!=='APPLIED'?'รอ workflow ประสาน':'ยังไม่มีคำสั่งสำหรับสถานะนี้'}}</p></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดงานเพิ่มเติม</button></section></template>
